CREATE DATABASE IF NOT EXISTS ifab_auction CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ifab_auction;
CREATE TABLE admins(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,status ENUM('active','inactive') DEFAULT 'active',last_login DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(30),role ENUM('grower','buyer') NOT NULL,status ENUM('pending','active','blocked') DEFAULT 'pending',password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE growers(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL UNIQUE,business_name VARCHAR(180),farm_location VARCHAR(255),verification_status ENUM('pending','verified','rejected') DEFAULT 'pending',FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE buyers(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL UNIQUE,organisation VARCHAR(180),billing_address TEXT,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE flower_categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,description TEXT);
CREATE TABLE flowers(id INT AUTO_INCREMENT PRIMARY KEY,grower_id INT NULL,name VARCHAR(150) NOT NULL,category VARCHAR(100) NOT NULL,price DECIMAL(12,2) NOT NULL DEFAULT 0,unit VARCHAR(40) DEFAULT 'bunch',quantity INT NOT NULL DEFAULT 0,image_url VARCHAR(500),youtube_url VARCHAR(500),status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(grower_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE site_videos(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,youtube_url VARCHAR(500) NOT NULL,description TEXT NULL,status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE auctions(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,flower_id INT NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NULL,base_price DECIMAL(12,2) NOT NULL,current_price DECIMAL(12,2) DEFAULT 0,status ENUM('draft','scheduled','live','completed','cancelled') DEFAULT 'scheduled',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(flower_id) REFERENCES flowers(id) ON DELETE SET NULL);
CREATE TABLE auction_items(id INT AUTO_INCREMENT PRIMARY KEY,auction_id INT NOT NULL,flower_id INT NOT NULL,quantity INT NOT NULL,FOREIGN KEY(auction_id) REFERENCES auctions(id) ON DELETE CASCADE,FOREIGN KEY(flower_id) REFERENCES flowers(id));
CREATE TABLE bids(id INT AUTO_INCREMENT PRIMARY KEY,auction_id INT NOT NULL,buyer_id INT NOT NULL,amount DECIMAL(12,2) NOT NULL,status ENUM('active','winning','outbid','rejected') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(auction_id) REFERENCES auctions(id),FOREIGN KEY(buyer_id) REFERENCES users(id));
CREATE TABLE orders(id INT AUTO_INCREMENT PRIMARY KEY,buyer_id INT NOT NULL,order_number VARCHAR(40) NOT NULL UNIQUE,total_amount DECIMAL(12,2) NOT NULL,shipping_address TEXT NULL,status ENUM('pending','confirmed','processing','shipped','out_for_delivery','delivered','cancelled') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(buyer_id) REFERENCES users(id));
CREATE TABLE order_items(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,flower_id INT NOT NULL,quantity INT NOT NULL,unit_price DECIMAL(12,2) NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(flower_id) REFERENCES flowers(id));
CREATE TABLE payments(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,transaction_ref VARCHAR(120),amount DECIMAL(12,2) NOT NULL,method VARCHAR(50),status ENUM('pending','paid','failed','refunded') DEFAULT 'pending',paid_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE news(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(220) NOT NULL,slug VARCHAR(240) UNIQUE,body LONGTEXT NOT NULL,image_url VARCHAR(500),status ENUM('draft','published') DEFAULT 'draft',published_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE events(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(220) NOT NULL,description TEXT,event_date DATETIME NOT NULL,venue VARCHAR(220),status ENUM('upcoming','completed','cancelled') DEFAULT 'upcoming');
CREATE TABLE enquiries(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,subject VARCHAR(220) NOT NULL,message TEXT NOT NULL,status ENUM('new','read','resolved') DEFAULT 'new',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notifications(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,title VARCHAR(180) NOT NULL,message TEXT NOT NULL,is_read TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE activity_logs(id INT AUTO_INCREMENT PRIMARY KEY,admin_id INT NULL,action VARCHAR(180) NOT NULL,details TEXT,ip_address VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(admin_id) REFERENCES admins(id) ON DELETE SET NULL);
CREATE TABLE settings(id INT AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(120) NOT NULL UNIQUE,setting_value TEXT);
